// Intelligent Content Selection & Caption Generation
const assets = $input.all();
const imageAssets = assets.filter(asset => 
  asset.json.mimeType && asset.json.mimeType.startsWith('image/')
);

if (imageAssets.length === 0) {
  return { json: { error: 'No image assets found in Drive' } };
}

// Smart asset selection based on time of day
const hour = new Date().getHours();
let assetPriority = [];

if (hour >= 7 && hour <= 11) {
  // Morning: Motivational/Professional content
  assetPriority = ['professional', 'team', 'tools', 'before'];
} else if (hour >= 12 && hour <= 17) {
  // Afternoon: Work in progress
  assetPriority = ['progress', 'action', 'work'];
} else {
  // Evening: Completed projects
  assetPriority = ['after', 'completed', 'finished'];
}

// Select appropriate asset
let selectedAsset = imageAssets[0]; // fallback
for (let priority of assetPriority) {
  const match = imageAssets.find(asset => 
    asset.json.name.toLowerCase().includes(priority)
  );
  if (match) {
    selectedAsset = match;
    break;
  }
}

// If no match, select random
if (!selectedAsset || selectedAsset === imageAssets[0]) {
  selectedAsset = imageAssets[Math.floor(Math.random() * imageAssets.length)];
}

// Dynamic caption templates based on content type
const captionTemplates = {
  morning: [
    "🌅 Starting another day of quality drywall work in the KW region! Professional results you can trust. Call (437) 830-4202 for your free estimate!",
    "☕ Good morning! Ready to transform your space with expert drywall services? Serving Kitchener, Waterloo, Cambridge & Guelph.",
    "🏗️ Monday motivation: Every wall we finish is a step toward your dream space. Professional drywall installation & repair."
  ],
  afternoon: [
    "🔨 Hard at work delivering paint-ready finishes! This is what 10+ years of drywall experience looks like.",
    "⚡ Progress update: Another satisfied client in the making! Quality drywall work that stands the test of time.",
    "🎯 Precision matters in drywall. Clean lines, smooth finish - that's the SoOptimal difference."
  ],
  evening: [
    "✨ Another successful project completed! From rough to paint-ready - we handle it all in the KW region.",
    "🏠 Transform your space with professional drywall services. This client is ready for paint! Who's next?",
    "💪 Day's work done! Quality drywall installation that homeowners love. Book your consultation today."
  ]
};

// Select appropriate caption
let timeCategory = 'afternoon';
if (hour >= 7 && hour <= 11) timeCategory = 'morning';
else if (hour >= 18 && hour <= 23) timeCategory = 'evening';

const templates = captionTemplates[timeCategory];
const selectedCaption = templates[Math.floor(Math.random() * templates.length)];

// Add call-to-action and hashtags
const cta = "\n\n📞 Ready for your project? Call (437) 830-4202 | 🌐 sooptimal.com";
const hashtags = "\n\n#SoOptimalContracting #Drywall #KitchenerWaterloo #Professional #QualityWork #FreeEstimate #HomeImprovement #Renovation #Construction #KW";

return {
  json: {
    assetId: selectedAsset.json.id,
    assetName: selectedAsset.json.name,
    imageUrl: selectedAsset.json.webContentLink,
    thumbnailUrl: selectedAsset.json.thumbnailLink,
    caption: selectedCaption + cta + hashtags,
    timeOfDay: timeCategory,
    timestamp: new Date().toISOString()
  }
};
